import sys, os; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import *
CHAPTERS = []
def ch(num, kicker, title, a, b, art_a="", art_b=""):
    """Two pages per chapter. Returns [pageA, pageB]; page A carries a marker for the contents."""
    A = page(f"<!--CH{num}-->" + head(f"chapter {num}  ·  {kicker}", title) + a, f"Chapter {num}", art=art_a)
    B = page(b, f"Chapter {num}")
    CHAPTERS.append((num, title)); return [A, B]
def pages():
    P = []
    P.append(cover("Early, Not Rushed", "a guide to flexible and accelerated homeschooling", "What worked for me, what didn't, and how to build a path around your child, for parents and students.", art_stairs(330, 190), pill="THE GUIDE FOR PARENTS AND STUDENTS"))
    P.append(page(head("the fine print", "About this guide") +
        f"<p>© 2026 {AUTHOR}. All rights reserved. Personal use only. Please don't copy, share or resell this file.</p>" +
        box("plain", "Please read", f"<p>{DISCLAIMER}</p><p>I am not a licensed teacher, counselor, psychologist or lawyer. I don't diagnose or give medical, mental-health or legal advice, and I can't promise any outcome, including early graduation. If you are worried about a child's well-being, please talk to a qualified professional.</p>") +
        box("story", "A note on how this was made", "<p>The experiences in this guide are mine. AI tools helped me draft and format parts of it, and I reviewed and edited the content myself. Please check rules and requirements with the official source for your state, district or college, since they change.</p>") +
        box("plain", "Other families' stories", "<p>I describe patterns I've seen, not specific families. I don't name anyone, and I've kept private details out.</p>"), "", run=False))
    toc_index = len(P); P.append("")  # contents placeholder
    P.append(page(head("start here", "Why this guide exists", "For parents, and for the students reading over their shoulder.") +
        '<div class="two"><div>'
        "<p>When I was in third grade, in-person school wasn't working for me. It taught one way at one speed, and I couldn't adapt to it. My family pulled me out, and I started homeschooling. That decision changed my life.</p>"
        "<p>I finished high school at 13 through FLVS Flex, earned my associate degree at 15 and my bachelor's at 17, and I'm now working on a master's. People always ask how. But the better question is <span class='hl'>how fit</span>: how did we build learning that fit me?</p>"
        f"</div><div style='flex:0 0 2.6in'>{art_stairs(250, 145)}</div></div>"
        "<p>This guide is one person's honest story plus the tools I wish my family had: readiness questions, check-ins, a way to spot gaps, questions to ask a college, and what to do when things get hard.</p>" +
        '<div class="two">' + box("worked", "It's for parents who", "<ul><li>are thinking about homeschooling or a flexible path</li><li>are already in it and wondering if it's working</li><li>wonder about early college</li><li>worry about socialization</li></ul>") +
        box("story", "It's for students who", "<ul><li>feel school doesn't fit</li><li>want a say in how they learn</li><li>are curious how someone did it</li><li>want words for what's working and what isn't</li></ul>") + '</div>' +
        box("try", "How to use it", "<p>Read the chapters that match where you are. Each ends with a tool you can use that week. You don't have to do everything, and you don't have to go fast.</p>"), "Start Here", art=art_compass(90)))
    # ---- Ch1
    P += ch(1, "my story", "My story, honestly",
        "<p>In third grade, I got pulled out of in-person school. It wasn't because I couldn't learn. The classroom was one linear, one-sided style, and I couldn't adapt to it. Because I was pulled out in the middle of the school year, I didn't get to say goodbye to most of my friends.</p>"
        "<p>Homeschooling changed the question from \"how do I fit this?\" to \"what fits me?\" I could work at my own pace, follow ideas I was curious about, and learn a lot about myself. And I had a voice: I gave my parents feedback about what worked and what didn't, and together we built the experience around me.</p>" +
        f"<div style='text-align:center;margin:.1in 0'>{art_stairs(420, 243)}</div>" +
        "<p>I finished all my classes quickly, graduated high school at 13, earned my associate degree at 15 and my bachelor's at 17. But please hear this: <span class='hl'>graduating early doesn't have to be the outcome.</span> It was mine. Homeschooling can lead to many other places.</p>",
        "<h2>It wasn't easy</h2><p>My first year of online school was the hardest part. At school, the classroom told me where to be and what to do all day. Online, I had lecture times and assignments, and once they were done, I was free. I wasn't used to that freedom. I also missed the social side so much that I honestly thought it didn't exist. My parents simply didn't know yet what they could sign me up for. It took about a year of settling in before they found the activities that filled the gap.</p>" +
        '<div class="quote">I told my parents I missed being in school. They didn\'t get defensive. They understood it was a process they were still learning too.</div>' +
        '<div class="two">' + box("worked", "What helped most", "<p>An online instructor <b>and</b> my own pace. I wasn't alone with the material, and I wasn't stuck on someone else's schedule.</p>") + box("didnt", "What I'd change", "<p>My outlook going in. I didn't know yet how to use all that freedom, and it took me longer than it needed to.</p>") + '</div>' +
        "<h3>Your timeline</h3>" + table(["", "Where we are", "What's working", "What isn't", "One thing we'll try"], [["Learning style", "", "", "", ""], ["Pace", "", "", "", ""], ["Daily structure", "", "", "", ""], ["Social life", "", "", "", ""]]),
        art_compass(90), art_bubbles(150, 70))
    # ---- Ch2
    P += ch(2, "readiness", "Ready, or pushed?",
        "<p>When people hear I graduated at 13, the first question is usually: <b>\"How do I know if my child is ready?\"</b> I'd change it slightly: <span class='hl'>Is this the right fit right now, and how will we know if it stops being the right fit?</span> Speed is a result. Fit is the goal.</p>"
        "<h2>Two kinds of readiness</h2>"
        '<div class="two">' + box("plain", "Academic", "<p>Can they do the work and <i>understand</i> it, not just finish it? Do they ask for more? Finishing quickly isn't the same as understanding deeply.</p>") + box("plain", "Emotional & social", "<p>Can they tell you when something is hard? Do they bounce back from a bad day? Do they want this, or are they agreeing because you do?</p>") + '</div>'
        "<h2>Ready vs. pushed</h2>" +
        table(["", "Ready", "Pushed"], [["Where it comes from", "The child's curiosity and pace", "An outside goal: a date, a comparison, a headline"], ["Who's asking", "Often the child", "Mostly the adults"], ["When it's hard", "They say so and the plan changes", "They hide it, or the plan doesn't change"], ["Rest and downtime", "Protected", "Squeezed out"]]),
        "<h2>Signs to slow down and talk</h2>" + box("didnt", "One sign isn't a verdict. Several together are a reason to pause.", "<ul><li>Dread or tears around schoolwork that wasn't there before</li><li>Losing interest in things they used to love</li><li>Cutting out friends and activities to keep up</li><li>Perfectionism, or fear of mistakes</li><li>Praise tied mainly to speed</li></ul><p class='fine'>I'm not a doctor or counselor. If you're worried about a child's well-being, please talk to a qualified professional.</p>") +
        box("story", "What helped me", "<ol><li>I had a say. I told my parents what worked and what didn't.</li><li>I worked at <i>my</i> pace.</li><li>I had an online instructor to turn to.</li><li>I had a social life: clubs, church groups, friends.</li><li>The hard first year was allowed.</li></ol>") +
        box("try", "Try this: the monthly check-in", "<p>Ask each month: What was the best part? The hardest? What would you change? Faster, slower or the same? Write it down. Change one thing.</p>"), art_sprout(100), art_stars())
    # ---- Ch3
    P += ch(3, "slowing down", "When acceleration is the wrong move",
        "<p>Acceleration is a tool. For some jobs it's great, and for others it's wrong. I graduated early, and I'm still going to tell you that for many children, moving fast isn't the answer.</p>"
        "<h2>When to slow down or stay put</h2><ol><li><b>The child doesn't want it.</b> If the motivation is mostly yours, the plan will crack the first time it's hard.</li><li><b>Depth is what they need.</b> Some kids want to go <i>deeper</i>, not faster: three months on one topic, ten books on one period of history. That's an excellent use of homeschooling.</li><li><b>There are gaps.</b> More speed adds weight to a weak base.</li><li><b>Rest and friends would be squeezed out.</b> That price is too high.</li><li><b>They're close to burned out.</b> Pause first, plan later.</li><li><b>You haven't checked what's waiting at the end.</b> Before racing toward a milestone like college, ask what's there.</li></ol>" +
        box("story", "From my experience", "<p>With school ending around 2, I had the rest of the afternoon for other activities and things I was interested in. That space mattered more than finishing a month sooner.</p>"),
        "<h2>What to do instead</h2>" +
        '<div class="two"><div><ul><li><b>Go deeper, not faster.</b> Projects, long reading, hands-on work.</li><li><b>Accelerate one subject,</b> not all of them.</li><li><b>Slow down on purpose.</b> Give a hard stretch more time.</li></ul></div><div><ul><li><b>Add enrichment:</b> art, coding, music, languages.</li><li><b>Build the social side.</b></li><li><b>Take a planned break.</b> Rest is part of learning.</li></ul></div></div>' +
        box("worked", "Pausing isn't failing", "<p>If you slow down, you haven't wasted anything. You've listened to what your child needs. That's the skill this whole guide is about.</p>") +
        "<h2>Tool: pause or continue?</h2>" + table(["Question", "Yes", "No"], [["Does the learner want to continue at this speed?", "", ""], ["Do they understand it, not only finish it?", "", ""], ["Are they sleeping, eating and seeing friends normally?", "", ""], ["Is there an adult they can talk to about stress?", "", ""], ["Is there room each week for something just fun?", "", ""]]) +
        "<p class='fine'>Mostly yes: continue and check monthly. Mixed: change one thing, recheck in two weeks. Mostly no: slow down, then talk about what's driving the pace.</p>", art_compass(90), art_stars())
    # ---- Ch4
    P += ch(4, "the route", "Mapping the route",
        "<p>There's no single path. Here are the main ones I know about, with honest trade-offs. The right one depends on your child and your state.</p>" +
        table(["Option", "Good for", "Trade-off"], [["<b>Stay on grade level, build depth</b>", "Children who want depth or balance, or aren't ready for more", "May feel slow to an eager child"], ["<b>Subject acceleration</b>", "A child clearly ahead in one subject", "Needs planning so courses fit together"], ["<b>Grade skipping</b>", "A child ready across the board, academically and emotionally", "Big step; gaps and social fit matter"], ["<b>Early graduation</b>", "A ready child who wants it, with a plan for what's next", "Graduating without a plan can leave a gap"], ["<b>Dual enrollment / early college</b>", "A child ready for adult classes", "Workload, schedules and age policies vary"], ["<b>Online instructor-led courses</b>", "Kids who like structure but need flexibility", "Some prefer live, in-person teaching"], ["<b>Mix and match</b>", "Most families, eventually", "Takes some juggling"]]),
        "<h2>How to choose</h2><ol><li><b>Start with the child:</b> face to face with an instructor, online with one, or no lectures at all?</li><li><b>Check the rules where you live.</b> Your state's education department and your district are the official sources.</li><li><b>Pick the smallest change that would help.</b></li><li><b>Try it for a term, then review.</b></li></ol>" +
        box("story", "My route", "<p>I finished high school through FLVS Flex, an online program with an online instructor and my own pace. Then I took a placement test, enrolled at a state college, and later transferred to a university. That route fit me. It may not fit you, and that's fine.</p>") +
        "<h3>Tool: route comparison</h3>" + table(["Option", "Fits our child because", "Risks", "Try it for"], [[""] * 4 for _ in range(4)]), art_stairs(190, 112), art_book(120, 88))
    # ---- Ch5
    P += ch(5, "foundations", "Avoiding gaps in the foundations",
        "<p>Moving fast is only a gift if the foundation underneath is solid. Otherwise you're building higher on a weak base.</p>"
        "<h2>What a gap looks like</h2><ul><li>They can do this week's work but struggle when something earlier comes back</li><li>They memorized steps without knowing why</li><li>They freeze on problems that mix several ideas</li><li>A subject that builds on itself, like math, suddenly feels impossible</li></ul>"
        "<h2>Where gaps hide</h2>" + '<div class="two">' + box("plain", "Math", "<p>Each level depends on the last.</p>") + box("plain", "Writing", "<p>Speed can hide weak organization.</p>") + '</div><div class="two">' + box("plain", "Reading", "<p>Fluent reading can hide shaky comprehension.</p>") + box("plain", "Study skills", "<p>Notes, time, asking for help.</p>") + '</div>' +
        box("story", "From my experience", "<p>Having an online instructor while working at my own pace meant there was someone to turn to when something didn't make sense. That's what let me move quickly without leaving holes behind.</p>"),
        "<h2>A simple gap check, monthly</h2><ol><li>Pick a topic from a few months ago.</li><li>Ask the learner to <b>explain it like they're teaching you.</b></li><li>Give 3-5 problems or a short writing task, with no hints.</li><li>Note what's easy, what takes effort, and what they can't do.</li><li><b>If something's shaky, go back before going forward.</b></li></ol>" +
        box("worked", "Going back isn't failing", "<p>It's what makes fast progress possible later.</p>") +
        "<h3>Tool: foundations audit</h3>" + table(["Subject", "Explains well", "Feels shaky", "Plan to fix", "Recheck on"], [[s, "", "", "", ""] for s in ["Math", "Writing", "Reading", "Science", "Study skills"]]), art_compass(90), art_stars())
    # ---- Ch6
    P += ch(6, "paperwork", "Records, transcripts and credentials",
        "<p>Paperwork isn't exciting, but it's what opens doors later. When a student is 13 and applying to a college program, the records have to speak for them.</p>"
        "<h2>What to keep</h2>" + checks(["Course list with dates, what was covered, and the result", "Transcripts from any school, online program or college", "Diploma and graduation records", "Work samples from key projects", "An activity log: clubs, groups, volunteering, internships", "Test results, if any", "Emails and forms with schools and colleges"]) +
        box("story", "From my experience", "<p>My path went through FLVS Flex for high school, a state college for the associate degree, and a university for the bachelor's. Keeping the paperwork from each step made the next one easier, and I can show my diploma, transcripts and degrees.</p>"),
        "<h2>A simple system</h2><ol><li>One folder per year, on paper and digital.</li><li>Update the course list every term.</li><li>Save official transcripts when they're issued.</li><li>Keep a running activity log.</li><li>Back everything up.</li></ol>" +
        box("try", "Check the rules where you live", "<p>Requirements for homeschool records, reporting and diplomas differ by state. Your state's education department and your district are the official sources. Don't rely on any blog, including this guide, for the legal parts.</p>") +
        "<h3>Tool: records tracker</h3>" + table(["Item", "Where it's stored", "Last updated", "Needed for"], [[x, "", "", ""] for x in ["Course list", "Official transcripts", "Diploma / graduation", "Activity log", "Work samples", "Test results"]]), art_book(120, 88), art_sprout(100))
    # ---- Ch7
    P += ch(7, "college", "Early college",
        "<p>Dual enrollment (sometimes called early college) generally means taking college courses while still in high school. Who qualifies, who pays and how credits transfer vary widely by state and college, so check yours.</p>"
        "<h2>My route</h2><p>I finished high school first. Then I took the placement test (the PERT, at the time) and enrolled at Palm Beach State College. It wasn't hard to get in, because on paper I had satisfied what was required. I took most of my associate classes online but still took part in things on campus. Then I transferred to Florida Atlantic University for my bachelor's.</p>" +
        '<div class="two">' + box("worked", "What worked", "<ul><li>Starting with online classes</li><li>Joining things on campus</li><li>Finding friends with shared interests</li></ul>") + box("didnt", "What was hard", "<ul><li>The shock when people learned my age</li><li>Moving to in-person classes</li></ul>") + '</div>' +
        box("story", "The in-person adjustment", "<p>At the university, I was back in a classroom in person for the first time in years. It took adaptation. It was the same kind of adjustment I'd made going from in-person school to homeschooling when I was young.</p>"),
        "<h2>Questions to ask the college</h2>" + table(["Question", "Answer"], [[q, ""] for q in ["Age and grade requirements? Any exceptions?", "Which tests or transcripts are needed?", "What does it cost? Any programs that help?", "Which credits transfer? (Get it in writing.)", "Online, in person or both?", "Who is our contact? Is there an advisor?", "What role do parents have for a minor?", "What's the withdrawal policy?"]]) +
        '<div class="two">' + box("try", "Start small", "<p>Take one or two classes first. Think of it as a test of fit.</p>") + box("worked", "Scholarships", "<p>I received a few, including ones specific to my college and one from an honors society. Ask early.</p>") + '</div>', art_stairs(190, 112), art_compass(90))
    # ---- Ch8
    P += ch(8, "friends", "Social life, and being young on campus",
        "<p>The two questions I hear most: <b>\"What about friends?\"</b> and <b>\"What's it like being the youngest?\"</b></p>"
        "<h2>Homeschool and social life</h2><p>My honest answer: I had as much social life as other kids, maybe more. But it wasn't there at the start. I was pulled out mid-year and didn't get to say goodbye to most of my friends, and for the first year I thought it didn't exist. It took about a year for my parents to find the local activities. After that, I was in local high school clubs and organizations and in church groups.</p>"
        "<h3>Build it on purpose</h3><ul><li>Clubs and organizations (check each group's rules)</li><li>Faith or community groups</li><li>Co-ops and classes</li><li>Volunteering</li><li>Sports and arts</li><li>Friends of different ages</li></ul>" +
        box("try", "Ask yourself", "<ul><li>How many regular activities does the week have?</li><li>Does my child have a friend they can talk to freely?</li><li>Are they invited, and do they invite others?</li></ul>"),
        "<h2>Being young among older students</h2><p><b>At the state college (starting at 13):</b> it wasn't bad. Most students were college freshmen, so I fit in. It was about adapting and finding friend groups with shared interests.</p><p><b>At the university (after my associate degree at 15):</b> a different ballpark. I found my footing. The campus even had a high school on it, so I made friends with a lot of high schoolers. I was a regular member of clubs like Konbit Kreyòl and the Black Student Union.</p>" +
        box("story", "The shock factor", "<p>There was a shock when I told people how old I was. But because of my path, I matured quickly, and that helped me fit in. In my second-to-last semester I took part in a legislative internship in Tallahassee, working with a state representative and living on my own. My age didn't get in the way.</p>") +
        "<h3>Tool: parent support plan</h3>" + table(["Situation", "Who can they talk to?", "What we'll do"], [[s, "", ""] for s in ["Feeling out of place", "Conflict with a classmate or instructor", "Feeling lonely", "Wanting to slow down"]]), art_sprout(100), art_bubbles(150, 70))
    # ---- Ch9
    P += ch(9, "rhythm", "A weekly rhythm that works",
        "<p>A good plan is one you can actually live in.</p>"
        "<h2>My own rhythm</h2><p>I worked from home. My day started at 9 and ended around 2, which left the rest of the day for other school activities and things I was interested in, like a trip to the park. The schedule itself worked. What I'd change is my <b>outlook</b>: at school, the classroom told me where to be. Online, I was free after my lectures and assignments, and I had to learn to treat that as a gift to plan around, not a gap.</p>" +
        f"<div style='text-align:center'>{art_wheel(260)}</div>" +
        box("try", "If your child is coming from a classroom", "<p>Talk about the free time <i>before</i> the first day: what do we do with it?</p>"),
        "<h2>Principles</h2><ol><li><b>Start with the learner.</b> Morning person or night owl?</li><li><b>Build around their learning style.</b></li><li><b>Protect rest.</b></li><li><b>Plan the social side.</b></li><li><b>Leave slack.</b> A packed schedule breaks on the first bad day.</li><li><b>Review monthly, change one thing.</b></li></ol>" +
        '<h3>Three shapes (adapt freely)</h3><div class="three">' + box("plain", "Focused mornings", "<p>Two focused blocks, a break, then lighter work and activities.</p>") + box("plain", "Project days", "<p>2-3 structured days, 1-2 project days, one community day.</p>") + box("plain", "Instructor + own pace", "<p>Fixed check-ins, flexible blocks, a weekly review.</p>") + '</div>' +
        "<h3>Tool: your week</h3>" + table(["Day", "Learning", "Break", "Friends / activity"], [[d, "", "", ""] for d in ["Mon", "Tue", "Wed", "Thu", "Fri"]]), art_book(120, 88), art_compass(90))
    # ---- Ch10
    P += ch(10, "tools", "Using AI and other tools without losing the learning",
        "<p>Tools can help a lot, and they can also do the thinking for you. The line is: <span class='hl'>use tools to support learning, not replace it.</span></p>"
        '<div class="two">' + box("worked", "Good uses", "<ul><li>Planning a schedule or project</li><li>Explaining an idea a different way (then checking it)</li><li>Generating extra practice</li><li>Feedback on a draft the student wrote</li><li>Exploring a topic and finding sources</li></ul>") + box("didnt", "Risky uses", "<ul><li>Getting answers without trying</li><li>Having it write the work</li><li>Trusting it without checking. It can be wrong</li><li>Sharing private information</li></ul>") + '</div>' +
        box("story", "A note", "<p>I'm not anti-tool. I used online instruction a lot. But the point was always understanding, not finishing faster.</p>"),
        "<h2>Simple rules for a family</h2><ol><li><b>Try first.</b> Struggle for a few minutes before asking for help.</li><li><b>Explain it back.</b> If you can't explain it without the tool, you haven't learned it.</li><li><b>Check the facts.</b> Find a second source.</li><li><b>The work is yours.</b></li><li><b>Follow each class's and program's rules.</b></li><li><b>Protect privacy.</b> Don't share a child's name, age, location or records, and check any tool's privacy terms and age rules.</li></ol>" +
        "<h3>Tool: our family tool rules</h3>" + "".join(f'<div class="fld"><b>{i}.</b>{lines(1)}</div>' for i in range(1, 6)), art_compass(90), art_stars())
    # ---- Ch11
    P += ch(11, "bumps", "When things go wrong",
        "<p>Things will go wrong. That doesn't mean the plan failed. It means you're in a real plan.</p>" +
        table(["The bump", "What to try"], [["<b>The hated first stretch.</b> A big change can feel awful at first.", "Give it time, but check in often. Mine took about a year, and mostly changed once we found community and routines."], ["<b>Motivation drops.</b>", "Ask why: too hard, too easy, too much, no say, too lonely? Change one thing."], ["<b>A course doesn't fit.</b>", "Switch the course, instructor or format. Staying in something that doesn't fit isn't a virtue."], ["<b>Burnout.</b>", "Slow down on purpose. Rest. Talk to someone you trust. If you're worried, talk to a professional."], ["<b>Falling behind.</b>", "Go back to foundations, rebuild, then move forward."], ["<b>The child wants to slow down.</b>", "That's allowed. Early graduation was my outcome, not the only good one."], ["<b>Parent doubt.</b>", "Normal. Talk to other families, mentors or a professional. Revisit the monthly check-in."]]),
        "<h2>A reset plan</h2><p>Use it when everything feels stuck.</p><ol><li><b>Stop adding.</b> Hold new commitments for two weeks.</li><li><b>Listen.</b> One honest conversation: what's the hardest part right now?</li><li><b>Rest.</b> Protect sleep, play and friends.</li><li><b>Pick one thing to change.</b></li><li><b>Recheck in two weeks.</b></li><li><b>Decide together:</b> continue, adjust or pause.</li></ol>" +
        box("didnt", "When to get help", "<p>If your child seems consistently sad, anxious, withdrawn or unsafe, or you're worried about their health, please contact a doctor, counselor or other qualified professional. That's beyond what this guide, or I, can do.</p>") +
        '<div class="two"><div>' + field("What's been hardest", 2) + field("The one thing we'll change", 2) + '</div><div>' + field("What we're pausing", 2) + field("Review date", 1) + '</div></div>', art_sprout(100), art_compass(90))
    P.append(page(head("where to go from here", "Keep going, gently") +
        "<ol><li><b>Pick one tool</b> from this guide and use it this week. The monthly check-in is a good start.</li><li><b>Ask your learner</b> what's working and what isn't. Then listen.</li><li><b>Change one thing.</b> Then check again.</li><li><b>Plan the social side and the free time</b> on purpose.</li><li><b>Remember the goal is fit.</b></li></ol>" +
        box("plain", "Where to check rules and requirements", "<p>I can share my experience, but rules change and differ by place. Check the official source:</p><ul><li>Your state's department of education</li><li>Your school district's home education or homeschool office</li><li>Any college you're considering (admissions, dual enrollment or advising office)</li><li>Your program (for example, the virtual school or curriculum provider)</li></ul>") +
        about_author() + f'<p class="fine">{DISCLAIMER}</p>', "Keep Going", art=art_sprout(100)))
    P.append(page('<div style="text-align:center;margin-top:2.3in">' + art_compass(150) + '<h1 style="margin-top:.3in">Thank you for reading</h1><div class="rule" style="margin:.1in auto"></div><p style="max-width:4.8in;margin:.2in auto">Every family finds its own way. I hope this helps you find yours.</p><p class="kicker" style="font-size:20pt;margin-top:.3in">Fabian</p></div>', "", run=False))
    # contents
    num_to_page = {}
    for idx, pg in enumerate(P):
        if isinstance(pg, str):
            for n, t in CHAPTERS:
                if f"<!--CH{n}-->" in pg: num_to_page[n] = idx + 1
    rows = "".join(f'<div class="q"><span class="n">{n}</span><span style="flex:1;font-size:12pt">{t}</span><span class="o">{num_to_page.get(n, "")}</span></div>' for n, t in CHAPTERS)
    P[toc_index] = page(head("inside", "Contents") + f'<div class="q"><span class="n"></span><span style="flex:1;font-size:12pt">Why this guide exists</span><span class="o">4</span></div>' + rows +
        box("story", "Tools in every chapter", "<p>Each chapter ends with a tool you can use that week: a check-in, a worksheet, a table, or a question list. They're also in the companion planner and bundles.</p>"), "Contents", art=art_book(120, 88))
    return P
if __name__ == "__main__":
    open(os.path.join(HERE, "guide.html"), "w").write(build_html(pages(), False, "Early, Not Rushed: The Guide"))
